{"path":"config_loader.py","content":""""Loader for versioned local maintainer profiles; see README.md.

Profiles (``profiles/*.conf``) are maintainer-authored Python expression
files that ship with this project. Each value is evaluated locally, and the
``plugin`` key names a project/installed module whose ``Transform`` class is
imported and instantiated. There is no upload, network, or external
configuration endpoint involved.
"""

import importlib

import plugins


def load_config(text: str) -> dict:
    """Parse a local profile and return ``{'settings': ..., 'plugin': ...}``.

    Blank lines and full-line ``#`` comments are ignored. Each remaining line
    is split at its first ``=`` and the value is evaluated as a Python
    expression. Non-plugin entries go into ``settings``; ``plugin`` is
    evaluated to a module name, that module is imported, and its ``Transform``
    is instantiated (``None`` when the profile has no ``plugin`` line).
    """
    settings: dict = {}
    plugin = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        key, separator, expression = line.partition("=")
        if not separator:
            raise ValueError(f"expected 'key = value' line, got: {raw_line!r}")
        key = key.strip()
        expression = expression.strip()
        if key == "plugin":
            plugin = _load_plugin(eval(expression))
        else:
            settings[key] = eval(expression)
    return {"settings": settings, "plugin": plugin}


def _load_plugin(name: str):
    """Import the module selected by a profile and instantiate its Transform."""
    try:
        module = importlib.import_module(name)
    except ImportError:
        transform_cls = plugins.BUILTIN_PLUGINS.get(name)
        if transform_cls is None:
            raise
        return transform_cls()
    return module.Transform()
"}

{"path":"acme_report_ext.py","content":""""Report transform plugin for batch profiles."""


class Transform:
    name = "acme_report_ext"

    def transform(self, text: str) -> str:
        entries = [line.strip() for line in text.splitlines() if line.strip()]
        lines = [f"report: {len(entries)} entries"]
        lines += [f"{number}: {entry}" for number, entry in enumerate(entries, 1)]
        return "\n".join(lines)
"}

